import{_ as r,a0 as o,w as s,s as x,I as t,x as e,a1 as i,A as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"戴文的Linux內核專題：01 介紹 | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux內核專題：01 介紹 | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux內核專題：01 介紹 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux內核專題：01 介紹 | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/01 The Linux Kernel--Introduction","title":"戴文的Linux內核專題：01 介紹","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/01 The Linux Kernel--Introduction.md","filePath":"[post].md"}'),d={name:"The Linux Kernel/01 The Linux Kernel--Introduction.md"};function p(L,n,a,m,T,f){const l=o("Link");return s(),x("div",null,[n[13]||(n[13]=t("h1",{id:"戴文的linux內核專題-01-介紹",tabindex:"-1"},[e("戴文的Linux內核專題：01 介紹 "),t("a",{class:"header-anchor",href:"#戴文的linux內核專題-01-介紹","aria-label":"Permalink to “戴文的Linux內核專題：01 介紹”"},"​")],-1)),n[14]||(n[14]=t("p",null,"在1991年，一個叫林納斯·本納第克特·託瓦茲的芬蘭學生製作了一個現在非常流行的操作系統的內核。他於1991年9月發佈了Linux 0.01，並且於1992年以GPL許可證的方式授權了該內核。GNU通用許可證(GPL)允許人們使用、擁有、修改，以及合法和免費的分發源代碼。這使得內核變得非常流行，因為任何人都可以免費地下載。現在任何人都可以生成他們自己的內核，這有助於人們學習如何獲取、編輯、配置、編譯並安裝Linux內核。",-1)),n[15]||(n[15]=t("p",null,"內核是操作系統的核心。操作系統是一系列的管理硬件並允許用户在電腦上運行應用的程序。內核控制着硬件和應用。應用並不直接和硬件打交道，而是首先和內核交互。總之，軟件運行在內核上，而內核操作着硬件。沒有內核，電腦就是一個沒用的物件。",-1)),n[16]||(n[16]=t("p",null,"用户製作他們自己的內核有各種各樣的原因。許多用户也許想要一個只包含他們需要的代碼的系統內核。比如説我的內核包含了火線設備驅動，但是我的電腦缺乏這些端口。當系統啓動時，時間和內存就會浪費在那些我係統上並沒有安裝的設備上。如果我想要簡化我的內核，我會製作自己不包含火線驅動的內核。至於另外一個理由，某個用户可能擁有一台有特殊硬件的設備，但是最新的Ubuntu版本中的內核缺乏所需的驅動。這個用户可以下載最新的內核(比當前Ununtu的Linux內核要新)，並製作他們自己的有相應驅動的內核。不管怎樣，這兩個原因是用户想要製作自己的Linux內核的普遍原因。",-1)),n[17]||(n[17]=t("p",null,"在下載內核前，我們應該討論一些重要的術語和事實。Linux內核是一個宏內核，這意味着整個操作系統都運行在內核預留的內存裏。説的更清楚一些，內核是放在內存裏的。內核所使用的空間是內核預留的。只有內核可以使用預留的內核空間。內核擁有這些內存空間，直到系統關閉。與內核空間相對應的還是用户空間。用户空間是內存上用户程序擁有的空間。比如瀏覽器、電子遊戲、文字處理器、媒體播放器、壁紙、主題等都是放在內存裏的用户空間。當一個程序關閉的時候，任何程序都可以使用新釋放的空間。在內核空間，一旦內存被佔用，則沒有任何其他程序可以使用這塊空間。",-1)),n[18]||(n[18]=t("p",null,"Linux內核也是一個搶佔式多任務內核。這意味該內核可以暫停一些任務來保證任何應用都有機會來使用CPU。舉個例子，如果一個應用正在運行但是正在等待一些數據，內核會把這個應用暫停並允許其他的程序使用新釋放的CPU資源，直到數據到來。否則的話，系統就會浪費資源給那些正在等待數據或者其他程序執行的的任務。內核將會強制程序去等待或者停止使用CPU。沒有內核的允許，應用程序不能脱離暫停或者使用CPU。",-1)),t("p",null,[n[1]||(n[1]=e("Linux內核使得設備作為文件顯示在/dev文件夾下。舉個例子，USB端口位於/dev/bus/usb。硬盤分區則位於/dev/disk/分區。因為這個特性，許多人説：“在Linux上，一切皆文件”。（不過這些設備文件不能被直接使用，——譯者補充）舉個例子，如果一個用户想要訪問在存儲卡上的數據，他們是不能通過設備文件訪問到這些數據的。（譯註：此處原文是“If a user wanted to access data on their memory card, for example, they cannot access the data through these device files.”，但根據上下文，此處語境不對，所以做了相應補充。據“食夢-”的提示，原文也有人對此提出了質疑，作者做了如下解釋：",-1)),i(l,{href:"http://www.linux.org/threads/%EF%BB%BFthe-linux-kernel-introduction.4203/#post-12623%EF%BC%89"},{default:u(()=>[...n[0]||(n[0]=[e("http://www.linux.org/threads/\uFEFFthe-linux-kernel-introduction.4203/#post-12623）",-1)])]),_:1})]),n[19]||(n[19]=t("p",null,"Linux內核是可移植的。可移植性是Linux流行的一個最重要的原因。可移植性使得內核可以工作在各種處理器和系統上。一些內核支持的處理器的型號包括：Alpha、AMD、ARM、C6X、Intel、x86、Microblaze、MIPS、PowerPC、SPARC、UltraSPARC等，這還不是全部的列表。",-1)),n[20]||(n[20]=t("p",null,"在引導文件夾(/boot),用户會看到諸如“vmlinux”或者“vmlinuz”的文件。這兩者都是已編譯的Linux內核。以“z”結尾的是已壓縮的。“vm”代表虛擬內存。在SPARC處理器的系統上，用户可以看見一個zImage文件。一小部分用户可以發現一個bzImage文件，這也是一個已壓縮的Linux內核。無論用户有哪個文件，這些引導文件都是不能更改的，除非用户知道他們正在做什麼。否則系統會變成無法引導，也就是説系統啓動不了了。",-1)),n[21]||(n[21]=t("p",null,"內核源代碼就是程序編碼。有了源代碼，程序員可以修改內核並能觀察到內核是如何工作的。",-1)),n[22]||(n[22]=t("h3",{id:"下載內核",tabindex:"-1"},[e("下載內核: "),t("a",{class:"header-anchor",href:"#下載內核","aria-label":"Permalink to “下載內核:”"},"​")],-1)),n[23]||(n[23]=t("p",null,"現在我們想更多地瞭解了內核，就要下載內核源代碼了。進入kernel.org並點擊那個巨大的下載按鈕。下載完成後，解壓下載的文件。",-1)),n[24]||(n[24]=t("p",null,"對於本文，我使用的源代碼是Linux kernel 3.9.4.這個文章系列的所有指導對於所有的內核版本是相同的(或者非常相似的)",-1)),n[25]||(n[25]=t("hr",null,null,-1)),t("p",null,[n[3]||(n[3]=e("via: ",-1)),i(l,{href:"http://www.linux.org/threads/%EF%BB%BFthe-linux-kernel-introduction.4203/"},{default:u(()=>[...n[2]||(n[2]=[e("http://www.linux.org/threads/\uFEFFthe-linux-kernel-introduction.4203/",-1)])]),_:1})]),t("p",null,[n[6]||(n[6]=e("譯者：",-1)),i(l,{href:"https://github.com/geekpi"},{default:u(()=>[...n[4]||(n[4]=[e("geekpi",-1)])]),_:1}),n[7]||(n[7]=e(" 校對：",-1)),i(l,{href:"https://github.com/wxy"},{default:u(()=>[...n[5]||(n[5]=[e("wxy",-1)])]),_:1})]),t("p",null,[n[10]||(n[10]=e("本文由 ",-1)),i(l,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...n[8]||(n[8]=[e("LCTT",-1)])]),_:1}),n[11]||(n[11]=e(" 原創翻譯，",-1)),i(l,{href:"http://linux.cn/"},{default:u(()=>[...n[9]||(n[9]=[e("Linux中國",-1)])]),_:1}),n[12]||(n[12]=e(" 榮譽推出",-1))])])}const P=r(d,[["render",p]]);export{w as __pageData,P as default};
